95	/**
96	 * Check if diagnostics can actually see the user's machine.
97	 * Returns true in Electron mode (local) or if running on localhost.
98	 * Returns false on deployed web servers where diagnostics would show container data.
99	 */
100	function canRunLocalDiagnostics() {
101	  if (process.env.ELECTRON_MODE) return true;
102	  // If running on localhost (dev mode), server IS the user's machine
103	  const port = process.env.PORT || '3001';
104	  if (port === '3001') return true; // dev default
105	  return false; // deployed (HF Spaces, etc.) — diagnostics show container, not user
106	}
