108	function noAccessMessage(toolName) {
109	  return `Cannot run ${toolName} — this would show server data, not the user's computer. ` +
110	    'Ask the user to click "Connect Computer" to connect their machine, or ask them to describe their setup.';
111	}
112	
113	// System Diagnostic Tools
114	
115	const getSystemInfo = tool(
116	  'get_system_info',
117	  "Get detailed info about the user's computer: OS version, CPU, RAM usage, disk space, uptime. Use to diagnose performance issues.",
118	  {},
119	  async () => {
120	    // In Electron/desktop mode, server diagnostics ARE the user's machine
