212	// Screenshot & Visual Pointing
213	
214	const takeScreenshot = tool(
215	  'take_screenshot',
216	  "Capture and analyze the user's screen to find a button, icon, or menu item they can't locate. Returns an annotated screenshot with the target highlighted. Only works when a relay agent is connected. Use this when the user says things like 'I can't find it', 'where is that button', 'I don't see it'.",
217	  {
218	    looking_for: z.string().describe("What the user is trying to find, e.g. 'Settings icon', 'Share button', 'Wi-Fi toggle'"),
219	  },
220	  async (args) => {
221	    if (!_requestScreenshotFn) {
222	      return textResult('Screenshot tool not available — server not configured.');
223	    }
224	
225	    const userId = getUserId();
226	
227	    // Request screenshot from relay agent
228	    const ssResult = await _requestScreenshotFn(userId);
229	    if (!ssResult || ssResult.error || !ssResult.imageBase64) {
230	      return textResult(
231	        'Could not take a screenshot. Make sure your computer is connected via the Connect Computer button. ' +
232	        (ssResult?.message || '')
233	      );
234	    }
235	
236	    // Use Claude vision to find what the user is looking for
237	    let targets = [];
238	    let description = '';
239	    try {
240	      if (anthropicApiKey) {
241	        const client = new Anthropic({ apiKey: anthropicApiKey });
242	        const visionResponse = await client.messages.create({
243	          model: 'claude-sonnet-4-20250514',
244	          max_tokens: 500,
245	          messages: [{
246	            role: 'user',
247	            content: [
248	              { type: 'image', source: { type: 'base64', media_type: 'image/png', data: ssResult.imageBase64 } },
249	              { type: 'text', text: `The user is looking for: "${args.looking_for}". Look at this screenshot of their actual screen.\n\nReturn ONLY valid JSON (no markdown):\n{"found": true/false, "targets": [{"x": pixel_x, "y": pixel_y, "label": "short label for what's here"}], "description": "one sentence describing where it is in plain language using spatial terms like top-right, bottom-left, etc."}` }
250	            ]
251	          }]
252	        });
253	        const jsonText = visionResponse.content[0]?.text || '';
254	        const cleanJson = jsonText.replace(/```json\n?|\n?```/g, '').trim();
255	        const parsed = JSON.parse(cleanJson);
256	        targets = parsed.targets || [];
257	        description = parsed.description || '';
258	      }
259	    } catch (err) {
260	      console.error('[MCP] Vision analysis failed:', err.message);
261	      description = `I took a screenshot but couldn't analyze it automatically. Here's your screen — look for ${args.looking_for}.`;
262	    }
263	
264	    // Annotate the screenshot if we have targets
265	    let annotatedBase64 = ssResult.imageBase64;
266	    if (targets.length > 0) {
267	      try {
268	        annotatedBase64 = await screenshotAnnotator.annotateScreenshot(ssResult.imageBase64, targets);
269	      } catch (err) {
270	        console.error('[MCP] Screenshot annotation failed:', err.message);
271	      }
272	    }
273	
274	    // Store the screenshot for the response
275	    _lastScreenshot = {
276	      imageBase64: annotatedBase64,
277	      description: description || `Screenshot of user's screen while looking for: ${args.looking_for}`,
278	      found: targets.length > 0,
279	    };
280	
281	    console.log(`[MCP] Screenshot taken: ${targets.length} target(s) found for "${args.looking_for}"`);
282	    return textResult(
283	      targets.length > 0
284	        ? `SCREENSHOT TAKEN: Found "${args.looking_for}". ${description}. The annotated screenshot is shown to the user.`
285	        : `SCREENSHOT TAKEN: Could not find "${args.looking_for}" on screen. ${description}. The screenshot is shown to the user — describe where to look using the image.`
286	    );
