783	function runFixStep(toolName, command) {
784	  const result = systemDiagnostics.runFixCommand(command);
785	  try {
786	    FixLog.create({
787	      session_id: _activeAutofixSessionId,
788	      user_id: _activeUserId,
789	      tool_name: toolName,
790	      command,
791	      exit_code: result.exitCode,
792	      stdout_tail: result.stdout,
793	      stderr_tail: result.stderr,
794	    });
795	  } catch (err) {
796	    console.error('[MCP] fix_log write failed:', err.message);
797	  }
798	  return result;
799	}
800	
801	function fixSummary(toolName, results) {
802	  const allOk = results.every(r => r.ok);
803	  const lines = results.map((r, i) =>
804	    r.ok
805	      ? `[step ${i + 1}] OK — ${r.stdout || '(no output)'}`
806	      : `[step ${i + 1}] FAILED (exit ${r.exitCode}) — ${r.stderr || '(no error message)'}`
807	  );
808	  return (allOk ? 'OK\n' : 'PARTIAL FAILURE\n') + lines.join('\n');
809	}
