978	  }
979	  for (const entry of entries) {
980	    const full = path.join(dir, entry.name);
981	    try {
982	      const stat = await fsp.stat(full);
983	      bytes += stat.size || 0;
984	      await fsp.rm(full, { recursive: true, force: true });
985	      removed += 1;
986	    } catch (_) {
987	      kept += 1;
988	    }
989	  }
990	  return { removed, kept, bytes };
