        exit_code: r.exitCode,
        stdout_tail: r.stdout,
        stderr_tail: r.stderr,
      });
    } catch (_) { /* non-critical */ }
    return textResult(r.ok ? `OK\n${r.stdout || '(no upgrades available)'}` : `FAILED (exit ${r.exitCode})\n${r.stderr}`);
  }
);

