function createPcPalMcpServer(opts = {}) {
  const mode = opts.mode || 'normal';
  const sandbox = mode === 'autofix-sandbox';

  // Common tools available in BOTH modes — diagnostics, safety, memory,
  // user/notes, vision, findings card.
  const commonTools = [
