    createFindings,
  ];

  // Normal-mode-only tools: teaching scaffolding, learning progression,
  // step sequences, guides, practice, buddy. None of these belong in
  // an autonomous-fix workflow.
  const normalOnlyTools = sandbox ? [] : [
    logSkillStarted,
