    const formatted = af.formatResult({ ok: true, url: 'https://support.apple.com/x', title: 'Hi', content: 'Body' });
    expect(formatted).toMatch(/^WEB_FETCH_RESULT:/m);
    expect(formatted).toMatch(/URL: https:\/\/support\.apple\.com\/x/);
