    for (const item of items) {
      if (!item || item.type !== 'web_search_result') continue;
      out.push({
        url: item.url || null,
        title: item.title || null,
        page_age: item.page_age || null,
        encrypted_content: item.encrypted_content || null,
      });
    }
  }
  return out;
}

